#!/usr/bin/env python3
"""wc.py — 纯 python3 实现的 wc 命令行工具: -l/-w/-c/--json/--help。"""
import argparse
import json
import sys


def count_stream(data: bytes):
    lines = data.count(b"\n")
    if data and not data.endswith(b"\n"):
        lines += 1
    return lines, len(data.split()), len(data)


def main():
    p = argparse.ArgumentParser(prog="wc.py", description="统计行数/单词数/字节数")
    p.add_argument("-l", action="store_true", help="只输出行数")
    p.add_argument("-w", action="store_true", help="只输出单词数")
    p.add_argument("-c", action="store_true", help="只输出字节数")
    p.add_argument("--json", action="store_true", help="JSON 输出")
    args = p.parse_args()
    lines, words, nbytes = count_stream(sys.stdin.buffer.read())
    if args.json:
        print(json.dumps({"lines": lines, "words": words, "bytes": nbytes}))
        return
    parts = []
    if args.l:
        parts.append(f"lines={lines}")
    if args.w:
        parts.append(f"words={words}")
    if args.c:
        parts.append(f"bytes={nbytes}")
    if not parts:
        parts = [f"lines={lines}", f"words={words}", f"bytes={nbytes}"]
    print(" ".join(parts))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""lru.py — collections.OrderedDict 实现 O(1) LRU;get 未命中返回 -1。"""
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.cap = capacity
        self.data = OrderedDict()

    def get(self, key):
        if key not in self.data:
            return -1
        self.data.move_to_end(key)
        return self.data[key]

    def put(self, key, value):
        if key in self.data:
            self.data.move_to_end(key)
        self.data[key] = value
        if len(self.data) > self.cap:
            self.data.popitem(last=False)


if __name__ == "__main__":
    c = LRUCache(2)
    c.put(1, 1)
    c.put(2, 2)
    assert c.get(1) == 1
    c.put(3, 3)              # 触发逐出 key=2
    assert c.get(2) == -1
    c.put(4, 4)              # 逐出 key=1
    assert c.get(1) == -1
    assert c.get(3) == 3
    assert c.get(4) == 4
    print("assert_ok")
